package server

import "time"

// Route table of the trajectory, terrain, RF statistics, navigation data,
// alert, replay / export and report endpoints. Appended to routes in init
// so docs/API.md lists them after the core groups.

const (
	grpPredict = "Prediction"
	grpTerrain = "Terrain"
	grpRF      = "RF statistics"
	grpNav     = "Navigation data"
	grpAlerts  = "Alerts"
	grpReplay  = "Replay, exports & reports"
)

const ttlPred = 5 * time.Second

var (
	pTerrainAnt = Param{"ant", "antenna ID (default: the first antenna; `visible`/`floor`: empty = best of all antennas)"}
	pTerrainK   = Param{"k", "effective earth radius factor for this path, clamped to 0.5..10 (default: the analysis' `k`, `config.terrain.kFactor`); the result's `k` is the value used"}
	pReport     = []Param{
		{"from, to", "time range in Unix ms: flights that overlap it (default: the last 24 h)"},
		{"hours", "alternative: the last N hours"}, {"days", "alternative: the last N days"},
		{"callsign", "callsign, `*` / `?` wildcards (e.g. `DLH*`)"}, {"reg", "registration, wildcards allowed"},
		{"icao", "ICAO address (6 hex digits) or a hex pattern with wildcards (`3C*`)"},
		{"type", "ICAO type designator, wildcards allowed (`A32?`)"}, {"operator", "operator: substring, or wildcards"},
		{"country", "country of registration (name): substring, or wildcards"}, {"squawk", "Mode A code, wildcards allowed (`77*`)"},
		{"military", "`1` only military, `0` no military"}, {"emergency", "`1` only flights that declared an emergency"},
		{"minDistKm", "farthest distance of the flight at least this"}, {"maxDistKm", "closest distance of the flight at most this"},
		{"minAlt", "highest altitude of the flight at least this (ft)"}, {"maxAlt", "lowest altitude of the flight at most this (ft)"},
		{"minPositions", "at least this many positions"},
		{"dep", "departure airport: exact ICAO or IATA code, case-insensitive (`EDDF`, `fra`)"},
		{"arr", "arrival airport: exact ICAO or IATA code, case-insensitive"},
		{"sort", "`start` (default) | `end` | `callsign` | `icao` | `reg` | `type` | `operator` | `country` | `maxDistKm` | `minDistKm` | `maxAlt` | `minAlt` | `maxGs` | `msgs` | `positions` | `duration` | `rssiMax` | `dep` | `arr`"},
		{"desc", "`1` / `0` (default: descending for times and numbers, ascending for text)"},
	}
)

func init() {
	routes = append(routes, extRoutes...)
}

var extRoutes = []Route{
	// ------------------------------------------------------------- prediction
	{Method: "GET", Path: "/api/prediction/live", Group: grpPredict, Access: AccessAdmin, API: apiPredictionLive, Cache: ttlLive,
		Summary: "Predicted position now of every aircraft the tracking filter follows (IMM filter, wind aware).",
		Notes:   "`coast` is true when the last real position is older than 4 s; such aircraft are also in `/api/aircraft` with `predicted:true` until `config.prediction.coastSec`. `conf` (0..1) decays with the age (about e^(-age/30)), `sigH` is the 1-sigma horizontal uncertainty in m. Only aircraft whose last position is at most `coastSec` old are listed. `409` when `config.prediction.enabled` is off."},
	{Method: "GET", Path: "/api/prediction/stats", Group: grpPredict, Access: AccessAdmin, API: apiPredictionStats, Cache: ttlPred,
		Summary: "Tracking filter counters and self-scored prediction quality per horizon and flight phase.",
		Notes:   "`horizons` has one row per horizon (5/15/30/60 s), predictor (`imm` = the filter, `cv` = constant velocity, `dr` = dead reckoning from the last report) and phase (`all`, `straight`, `turn`, `vertical`): median / p90 / p95 error in km, `calib95` (share of real positions inside the predicted 95 % ellipse, ideal 0.95). `skill[].skillPct` = how much better than dead reckoning (%). Only positions with 1-sigma <= 60 m are scored (MLAT excluded)."},
	{Method: "GET", Path: "/api/prediction/path/{icao}", Group: grpPredict, Access: AccessAdmin, API: apiPredictionPath, Sample: "/api/prediction/path/{live}?horizon=60&step=10",
		Summary: "Predicted path of one aircraft with growing uncertainty ellipses, and when terrain will hide it.",
		Params:  []Param{{"horizon", "seconds ahead, 10..900 (default `config.prediction.pathSec`)"}, {"step", "seconds between points, 1..300 (default 10; at most 301 points)"}},
		Notes:   "`learned` (when the aircraft has a current position, track and speed) is the path predicted from the recent surrounding traffic (`/api/prediction/learned`). `points[].dt` seconds after `t0`; `ell` is the 1-sigma error ellipse (`a`, `b` in m, `dir` = major axis deg true). `plan`: `decay` (turn rolls out), `capture` (turning to the selected heading), `hold` (racetrack), `ground`. `terrain` (null until the terrain analysis exists): `lostAtMs` / `acquiredAtMs` when the path crosses the terrain radio horizon (0 = not within the path). `404` when the aircraft is unknown or has had no position for longer than 120 s."},
	{Method: "GET", Path: "/api/prediction/learned", Group: grpPredict, Access: AccessAdmin, API: apiPredictionLearned,
		Summary: "The learned traffic-flow predictor: learned cells, aircraft followed, and its self-check against dead reckoning at 30 and 60 s (mean errors, share of predictions where it was closer, the blend weight it corrected itself to).",
		Notes:   "The learner records, per 0.1-degree cell, altitude band and 30-degree heading sector, how the traffic that passed turned over the next 30 / 60 s (time-decayed, half-life 3 h), and predicts by applying those turn rates (`learned` in `/api/prediction/path/{icao}`). Every 15 s per aircraft it scores a learned and a straight prediction against the real position and moves the blend `weight` towards the closer one. Memory only: it relearns within hours after a restart."},
	{Method: "GET", Path: "/api/prediction/intent/{icao}", Group: grpPredict, Access: AccessAdmin, API: apiPredictionIntent, Sample: "/api/prediction/intent/{live}",
		Summary: "Intent analysis of one aircraft: phase, holding, approach, closest approach to the station, level-off.",
		Notes:   "`phase`: `ground` | `climb` | `cruise` | `descent` | `approach` | `holding` | `turning` | `unknown`. `cpa`: closest approach to the receiver within 30 min (`inSec` 0 = now / moving away). `approach` needs imported runway data (`/api/navdata/import`). `404` as for `path`."},
	{Method: "GET", Path: "/api/prediction/proximity", Group: grpPredict, Access: AccessAdmin, API: apiPredictionProximity, Cache: ttlPred,
		Summary: "Predicted close approaches between airborne aircraft (informational only, not an ATC/TCAS function).",
		Params: []Param{{"km", "only pairs currently closer than this, 1..200 km (default 40)"}, {"horizon", "look-ahead seconds, 10..600 (default 120)"},
			{"hkm", "horizontal threshold km (default 9.26 = 5 NM)"}, {"vft", "vertical threshold ft (default 1000)"}, {"max", "most pairs returned, 1..1000 (default 200)"}},
		Notes: "`pairs` sorted by `severity` = max(hDist/hkm, vSep/vft) at the closest point (`tcpa` s from now); <= 1 means both thresholds are violated."},

	// ---------------------------------------------------------------- terrain
	{Method: "GET", Path: "/api/terrain/status", Group: grpTerrain, Access: AccessAdmin, API: apiTerrainStatus,
		Summary: "Terrain analysis job (download / sampling / coverage progress), result availability, tile cache.",
		Notes:   "Poll every second while `job.state` is `running` (`job.phase` `tiles` -> `terrain` -> `coverage`, `job.progress` 0..1), else rarely. `dataComplete=false`: some elevation tiles were missing (read as sea level). Show `attribution` with a link to `attributionUrl` wherever terrain-derived layers are visible. The analysis runs automatically when the receiver is located and `config.terrain.autoPrefetch` is on (about 30-40 MB of tiles for 450 km, downloaded once), and again after a change of position, antenna heights, `kFactor` or `radiusKm`."},
	{Method: "POST", Path: "/api/terrain/prefetch", Group: grpTerrain, Access: AccessAdmin, API: apiTerrainPrefetch, Admin: true, NoAuto: true,
		Summary: "Download the elevation tiles and run the terrain analysis now (also when automatic prefetching is off).",
		Params:  []Param{{"force", "`1` re-runs it ignoring the result cache"}},
		Returns: "`{\"started\":bool,\"job\":JobStatus}`; `409` when terrain is disabled or the receiver is not located."},
	{Method: "POST", Path: "/api/terrain/recompute", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/recompute", nil), Admin: true, NoAuto: true,
		Summary: "Re-run the last terrain analysis ignoring caches (also resets the download back-off).",
		Returns: "`202 {\"started\":bool,\"job\":JobStatus}`; `409` when nothing was submitted yet."},
	{Method: "POST", Path: "/api/terrain/cancel", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/cancel", nil), Admin: true, NoAuto: true,
		Summary: "Cancel a running terrain job (the previous result stays).", Returns: "`JobStatus`"},
	{Method: "GET", Path: "/api/terrain/coverage", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/coverage", nil),
		Summary: "The complete terrain analysis: per antenna the horizon panorama, line-of-sight and radio coverage rings per altitude, advice.",
		Params:  []Param{{"ant", "antenna ID whose site advice is returned in `advice` (default: the first antenna); `404` for an unknown antenna"}},
		Returns: "`terrain.Analysis` JSON (0.3-1 MB: fetch once per `key`, see `/api/terrain/status`). Per antenna: `horizon`, `los[]` and `radio[]` (`altFt`, `rangeKm[]` per bearing step, `minKm`, `maxKm`, `meanKm`, `areaKm2`), `advice`. `503` until the first analysis finished."},
	{Method: "GET", Path: "/api/terrain/coverage.geojson", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/coverage.geojson", nil), ContentType: "application/geo+json", Sample: "/api/terrain/coverage.geojson?kind=radio",
		Summary: "Theoretical coverage per altitude as GeoJSON polygons for the map.",
		Params:  params(pTerrainAnt, Param{"kind", "`los` (geometric line of sight with refraction; default) or `radio` (link budget incl. diffraction)"}),
		Returns: "FeatureCollection, one Polygon per altitude (highest first), properties `kind`, `antennaId`, `altFt`, `altM`, `areaKm2`, `meanKm`, `maxKm`, `minKm`, `smoothKm`, `capped`, `color`. `503` before the first analysis, `404` unknown antenna."},
	{Method: "GET", Path: "/api/terrain/horizon", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/horizon", nil),
		Summary: "Horizon panorama of one antenna: terrain mask angle, distance and height of the skyline per bearing.",
		Params:  params(pTerrainAnt),
		Returns: "`terrain.Horizon` JSON: `bearingDeg[]`, `elevationDeg[]`, `distanceKm[]`, `terrainM[]`, `nearestObstacleKm[]`, `smoothDipDeg` (smooth-earth horizon dip), `meanSkylineDeg`, `maxSkylineDeg`, `noDataFraction`."},
	{Method: "GET", Path: "/api/terrain/panorama", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/horizon", nil),
		Summary: "Same as `/api/terrain/horizon`.", Params: params(pTerrainAnt),
		Returns: "`terrain.Horizon` JSON (see `/api/terrain/horizon`)."},
	{Method: "GET", Path: "/api/terrain/advice", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/advice", nil),
		Summary: "Antenna site advice: coverage gain of a higher mast, worst sectors with the limiting ridge, ready-made sentences.",
		Params:  params(pTerrainAnt),
		Returns: "`terrain.SiteAdvice` JSON: `summary[]` sentences, `heights[]` (`extraM`, `areaKm2[]` per altitude, `areaGainPct[]`), `km2PerMetre[]`, `sectors[36]` and `worstSectors[]` (`blockedPct`, `limitDistKm`, `limitLat`, `limitLon`); `antennaId` says which antenna it is for. `503` before the first analysis, `404` unknown antenna."},
	{Method: "GET", Path: "/api/terrain/floor", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/floor", nil), Sample: "/api/terrain/floor?cell=0.5",
		Summary: "Coverage floor grid: lowest altitude visible from the antenna per cell.",
		Params:  params(pTerrainAnt, Param{"cell", "cell size in degrees (default 0.05 = the heat-map cells)"}),
		Returns: "`{cellDeg, south, west, north, east, rows, cols, floorFt[] (row 0 = south, -1 = not visible), heatAligned}`"},
	{Method: "GET", Path: "/api/terrain/floor-image", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/floor-image", nil), Sample: "/api/terrain/floor-image?w=256",
		Summary: "Coverage floor as a map image: URL, corner coordinates and legend for a MapLibre `image` source.",
		Params:  params(pTerrainAnt, Param{"w", "image width px (default 1024, max 2048)"}),
		Returns: "`{url, width, height, coordinates[4][lon,lat] (TL, TR, BR, BL), legend[{maxFt, color, label}], key}`"},
	{Method: "GET", Path: "/api/terrain/floor.png", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/floor.png", nil), NoAuto: true, ContentType: "image/png",
		Summary: "The coverage floor PNG (Web Mercator rows, transparent where nothing is visible). Use the `url` from `/api/terrain/floor-image`.",
		Params:  params(pTerrainAnt, Param{"w", "width px"}, Param{"k", "cache buster (analysis key)"}),
		Returns: "`image/png`"},
	{Method: "GET", Path: "/api/terrain/visible", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/visible", nil), Sample: "/api/terrain/visible?lat=50.4&lon=9.1&altFt=3000",
		Summary: "Is a point above the terrain radio horizon? (~100 ns, from the panorama.)",
		Params:  params(Param{"lat, lon", "degrees (required)"}, Param{"altFt", "altitude ft AMSL (required)"}, pTerrainAnt),
		Returns: "`{known, visible, marginDeg, elevationDeg, skylineDeg, floorFt, distKm, bearingDeg, beyondRange, antennaId}`"},
	{Method: "GET", Path: "/api/terrain/los", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/los", nil), Sample: "/api/terrain/los?lat=50.5&lon=9.2&altFt=10000&profile=0",
		Summary: "Line of sight from the antenna to one point: obstruction, Fresnel clearance, diffraction loss and the terrain profile.",
		Params:  params(Param{"lat, lon", "degrees (required)"}, Param{"altFt", "altitude ft AMSL (required)"}, pTerrainAnt, Param{"profile", "`0` omits the profile array"}, pTerrainK),
		Returns: "`{clear, groundKm, slantKm, bearingDeg, elevationDeg, obstruction|null, minClearanceM, fresnelRatio, fresnel60Clear, diffractionDb, edges[], fsplDb, gasDb, totalLossDb, noDataSamples, profile[{distKm, lat, lon, terrainM, bulgeM, rayM, fresnelM}]}`. Downloads the path tiles on demand (up to 60 s)."},
	{Method: "GET", Path: "/api/terrain/profile", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/los", map[string]string{"alt": "altFt"}), Sample: "/api/terrain/profile?lat=50.5&lon=9.2&alt=10000",
		Summary: "Same as `/api/terrain/los` with `alt` as the altitude parameter, for the path profile chart.",
		Params:  params(Param{"lat, lon", "degrees (required)"}, Param{"alt", "altitude ft AMSL (required; `altFt` also accepted)"}, pTerrainAnt, pTerrainK),
		Returns: "Same as `/api/terrain/los`, always with `profile`."},
	{Method: "GET", Path: "/api/terrain/elevation", Group: grpTerrain, Access: AccessAdmin, Raw: terrainRaw("/api/terrain/elevation", nil), Sample: "/api/terrain/elevation?lat=50.1&lon=8.7",
		Summary: "Terrain elevation at a point from the elevation tiles (downloads the tile when missing).",
		Params:  params(Param{"lat, lon", "degrees (required)"}, Param{"z", "tile zoom (default 12)"}),
		Returns: "`{lat, lon, elevM, ok, zoom}` (`ok=false`: no data, sea level assumed)."},

	// ------------------------------------------------------------------- rf
	{Method: "GET", Path: "/api/rf/summary", Group: grpRF, Access: AccessAdmin, API: apiRFSummary,
		Summary: "Headline RF numbers: health score, frame rate, channel occupancy, noise / decode floor, detection range, radars, GNSS index, advice (`advice[]` sentences and `adviceItems[]` `{code,text,data}`).",
		Notes:   "All `/api/rf/*` sections come from one sliding ~1 h statistics window (`windowSec`) shared between the endpoints (recomputed at most every 2 s). Fractions are 0..1, `*Pct` percent, unknown values `null`. `409` when `config.rfStat.enabled` is off."},
	{Method: "GET", Path: "/api/rf/report", Group: grpRF, Access: AccessAdmin, API: apiRFReport,
		Summary: "Everything below in one document (`rfstat.Report`)."},
	{Method: "GET", Path: "/api/rf/signal", Group: grpRF, Access: AccessAdmin, API: apiRFSignal,
		Summary: "Signal levels: RSSI histogram, decode floor, noise-floor estimate, overload share, per antenna / range ring / elevation, fading, multipath, aspect.",
		Notes:   "`noiseFloorEstDbfs` is an estimate (decode floor minus an assumed decode SNR, `assumedDecodeSnrDb`); label it as such. Strong = within 3 dB of full scale."},
	{Method: "GET", Path: "/api/rf/detection", Group: grpRF, Access: AccessAdmin, API: apiRFDetection,
		Summary: "Reception probability of position / velocity / identification squitters versus distance, elevation, bearing and RSSI; 50 % / 90 % range; update gaps.",
		Notes:   "Pd = received / expected squitters per aircraft in 10 s windows (nominal rates 2/s, 2/s, 0.2/s). `vsDistance` etc. are parallel arrays per bin (`lo`, `hi`, `pos`, `vel`, `ident`, `expected`)."},
	{Method: "GET", Path: "/api/rf/intervals", Group: grpRF, Access: AccessAdmin, API: apiRFIntervals,
		Summary: "Position update intervals per range band: percentiles and the probability that a position is at most T seconds old.",
		Notes:   "`gaps[].pUpdate[i]` belongs to `tSec[i]` (2, 4, 5, 8, 12 s)."},
	{Method: "GET", Path: "/api/rf/channel", Group: grpRF, Access: AccessAdmin, API: apiRFChannel,
		Summary: "1090 MHz channel: frames per DF, occupancy, CRC failures, garble model, load curve, bursts, last 5 minutes per second.",
		Notes:   "`overlapProb` is the Poisson probability that another reply overlaps one at the measured rate; `excessFail` = failures beyond that (interference / noise); `impliedRate` = channel rate that would explain the failures (FRUIT)."},
	{Method: "GET", Path: "/api/rf/interrogators", Group: grpRF, Access: AccessAdmin, API: apiRFInterrogators,
		Summary: "Interrogator census from DF11 replies (II / SI codes, rates, lock-out), surveillance reply rates, Comm-B mix, ACAS activity.",
		Notes:   "Reply `{t, interrogators}`: `t` is the time of the RF report (Unix ms; the end of every per-minute `timeline`), `interrogators` the census object (before this version it was returned bare, without `t`). II 0 includes DF11 acquisition squitters (`acqSquitter`)."},
	{Method: "GET", Path: "/api/rf/timing", Group: grpRF, Access: AccessAdmin, API: apiRFTiming,
		Summary: "Squitter timing from the receiver's GPS timestamps: interval histograms per type, even/odd alternation, non-compliant transmitters.",
		Notes:   "`available` is false without GPS timestamps. One receiver cannot do TOA ranging (`note`)."},
	{Method: "GET", Path: "/api/rf/fleet", Group: grpRF, Access: AccessAdmin, API: apiRFFleet,
		Summary: "Fleet / equipage census: ADS-B versions, NIC / NACp / SIL, poor integrity share, emitter categories, TC28/29/31 use, GNSS vs baro altitude, GNSS interference.",
		Notes:   "Poor integrity = NACp < 8 or NIC < 7 or SIL < 3."},
	{Method: "GET", Path: "/api/rf/gnss", Group: grpRF, Access: AccessAdmin, API: apiRFGNSS,
		Summary: "GNSS interference index: share of ADS-B aircraft with degraded navigation integrity, per minute (24 h) and per polar map cell.",
		Notes:   "Degraded = NACp < 5 after having reported >= 8, or NIC < 5 after >= 7. `cells`: 10 degree x 50 km sectors around the station with centre `lat` / `lon`, colour by `index` (%)."},
	{Method: "GET", Path: "/api/rf/health", Group: grpRF, Access: AccessAdmin, API: apiRFHealth,
		Summary: "RF health: score 0..100 (-1 = no data), scored items with plain-language text, blocked sectors, advice."},
	{Method: "GET", Path: "/api/rf/history", Group: grpRF, Access: AccessAdmin, API: apiRFHistory, Cache: ttlMed,
		Params:  pRange,
		Summary: "Hourly RF summaries (frame rate, occupancy, CRC failures, Pd, 90 % range, health ...), oldest first.",
		Notes:   "Default 7 days. Closed clock hours only (the current hour appears when it is over)."},

	// --------------------------------------------------------------- navdata
	{Method: "GET", Path: "/api/navdata/status", Group: grpNav, Access: AccessAdmin, API: apiNavStatus,
		Summary: "Imported reference datasets (rows, import time, source, licence), downloadable sources, import state, options and attribution.",
		Notes:   "Nothing is downloaded automatically. Airports, runways, navaids and countries come from OurAirports (public domain), routes from the Virtual Radar Server standing data (CC0). Show `attribution`."},
	{Method: "POST", Path: "/api/navdata/import", Group: grpNav, Access: AccessAdmin, API: apiNavImport, Admin: true, NoAuto: true,
		Summary: "Start downloading and importing reference datasets in the background.",
		Body:    "`{\"datasets\":[\"countries\",\"airports\",\"runways\",\"navaids\",\"routes\"],\"force\":false}` (empty body or empty list = all; about 25 MB in total)",
		Returns: "`{\"started\":true,\"import\":ImportStatus}`; `409` when an import is running.",
		Notes:   "Poll `/api/navdata/progress`. A failed or cancelled dataset keeps its previous contents. A notice is sent when the import finished."},
	{Method: "GET", Path: "/api/navdata/progress", Group: grpNav, Access: AccessAdmin, API: apiNavProgress,
		Summary: "State of the current or last import (`navdata.ImportStatus`): `running`, `progress{dataset, stage, bytesRead, bytesTotal, records, index, count}`, `fraction` 0..1, `result`, `error`."},
	{Method: "POST", Path: "/api/navdata/cancel", Group: grpNav, Access: AccessAdmin, API: apiNavCancel, Admin: true, NoAuto: true,
		Summary: "Cancel a running import.", Returns: "`{\"cancelled\":true,\"import\":ImportStatus}`"},
	{Method: "POST", Path: "/api/navdata/route-cache/clear", Group: grpNav, Access: AccessAdmin, API: apiNavRouteCacheClear, Admin: true, NoAuto: true,
		Summary: "Forget the cached online route look-ups.", Returns: "`{\"ok\":true}`"},
	{Method: "GET", Path: "/api/navdata/airports", Group: grpNav, Access: AccessViewer, API: apiNavAirports, Cache: ttlShort, Sample: "/api/navdata/airports?lat=50.05&lon=8.6&radiusKm=300&minSize=medium",
		Summary: "Airports in a box or around a point, largest first; optionally with runways or as a GeoJSON map overlay.",
		Params: []Param{{"bbox", "`S,W,N,E` degrees (W > E crosses the antimeridian)"}, {"lat, lon", "centre instead of `bbox` (default: the receiver)"},
			{"radiusKm", "radius around lat, lon, up to 5000 (default 100)"},
			{"minSize", "`large` | `medium` | `small` (default) | `other` | `all`"}, {"limit", "1..5000 (default 500)"},
			{"runways", "`1` attaches the runways"}, {"format", "`geojson` = FeatureCollection with `kind` `airport` points (label `code`), `runway` polygons, `centerline` lines (needs `runways=1`)"}},
		Notes: "Map overlay: fetch on `moveend` with the view as `bbox`, `runways=1&format=geojson`, `minSize` by zoom (<= 6 large, <= 8 medium, else small). Empty until the airports are imported."},
	{Method: "GET", Path: "/api/navdata/search", Group: grpNav, Access: AccessPublic, API: apiNavSearch, Sample: "/api/navdata/search?q=frankfurt",
		Summary: "Search airports by code or name.", Params: []Param{{"q", "text (required)"}, {"limit", "1..200 (default 20)"}}},
	{Method: "GET", Path: "/api/navdata/navaids", Group: grpNav, Access: AccessPublic, API: apiNavNavaids, Cache: ttlShort, Sample: "/api/navdata/navaids?bbox=49,7,51,10",
		Summary: "Radio navigation aids (VOR, DME, NDB, TACAN) in a box.",
		Params:  []Param{{"bbox", "`S,W,N,E` degrees (required)"}, {"types", "comma separated, e.g. `VOR,VOR-DME,NDB`"}, {"limit", "1..5000 (default 500)"}}},
	{Method: "GET", Path: "/api/navdata/airport/{code}", Group: grpNav, Access: AccessPublic, API: apiNavAirport, Sample: "/api/navdata/airport/{airport}",
		Summary: "One airport by ICAO, IATA, ident or GPS code, with its runways and usable landing directions.",
		Notes:   "`404` when unknown (or nothing imported)."},
	{Method: "GET", Path: "/api/navdata/route/{callsign}", Group: grpNav, Access: AccessPublic, API: apiNavRoute, Sample: "/api/navdata/route/{route}",
		Summary: "Route of a callsign (standing data, then the opt-in online look-up) with airports, great-circle path and a plausibility check.",
		Params:  []Param{{"lat, lon", "current position of the aircraft: enables `check` (plausible / doubtful)"}},
		Notes:   "Call lazily (when the user opens an aircraft), not for every aircraft: the live picture already carries `route` from the offline data. The online look-up (adsbdb.com) only runs for an admin caller with `config.navData.routes.online`; other callers get the standing data and an already cached answer and is cached (24 h, unknown 12 h) and paced (2 s, 1000/day; `429` when exhausted). `found:false` when unknown. `path` is `[lon, lat]` with unwrapped longitudes."},
	{Method: "GET", Path: "/api/navdata/photo/{icao}", Group: grpNav, Access: AccessPublic, API: apiNavPhoto, NoAuto: true, Sample: "/api/navdata/photo/3C6444",
		Summary: "Aircraft photo metadata from planespotters.net (opt-in): thumbnail, large image, link and photographer.",
		Params:  []Param{{"reg", "registration (improves the match)"}},
		Notes:   "`409` unless `config.navData.photos` is on and `config.navData.photoContact` is set (planespotters.net requires a contact in the User-Agent). Show the thumbnail only together with `attribution` and link it to `link`; never when `found` is false. Cached 7 days (2 days when none)."},

	// ---------------------------------------------------------------- alerts
	{Method: "GET", Path: "/api/alerts/rules", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRules,
		Summary: "All alert rules (built-in defaults and user rules), sorted by id.",
		Notes:   "Rule JSON: `{id, name, description?, enabled, builtin?, severity (info|warning|critical), match: Cond, cooldownSec, ruleCooldownSec?, includePredicted?, message?, actions: {notify, sound, log, webhook?, highlight?}, created, updated}`. `includePredicted` (default false): rules with an `altitude`, `distance`, `geofence` or `bearing` leaf ignore aircraft shown at a predicted (coasting) position unless it is true. Cond: a group `{op: and|or, conds: [...], negate?}` or a leaf `{type, ...}`; leaf types `icao`, `reg`, `callsign`, `operator`, `actype`, `category`, `country`, `squawk` (`values` globs), `military` / `onGround` / `newAirframe` (`value`), `emergency` (`values`), `altitude` / `speed` / `vrate` / `distance` / `adsbVersion` / `nic` / `rssi` (`min`, `max`), `bearing` (`from`, `to`), `geofence` (`lat`, `lon`, `radiusKm` or `polygon` [[lon,lat]...], `inside`), `source`, `watchlist` (`values` list names), `system` (`values` event kinds: `record`, `feed_down`, `feed_up`, `ntp_unsync`, `ntp_sync`, `range_collapse`, `range_restored`, `custom`, `new_airframe`, or `kind:KEY*`). Message placeholders: `/api/alerts/placeholders`."},
	{Method: "POST", Path: "/api/alerts/rules", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRuleCreate, Admin: true, NoAuto: true,
		Summary: "Create a rule.", Body: "a Rule without `id` (unknown fields are rejected, at most 64 kB)",
		Returns: "the stored Rule (id `r-...`); `400` with a readable message when invalid, `409` beyond 500 rules."},
	{Method: "GET", Path: "/api/alerts/rules/{id}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRule, Sample: "/api/alerts/rules/builtin-military",
		Summary: "One rule.", Notes: "`404` when unknown."},
	{Method: "PUT", Path: "/api/alerts/rules/{id}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRuleUpdate, Admin: true, NoAuto: true,
		Summary: "Replace a rule (built-in rules may be edited; reset-defaults restores them).", Body: "a Rule", Returns: "the stored Rule; `404` when unknown."},
	{Method: "DELETE", Path: "/api/alerts/rules/{id}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRuleDelete, Admin: true, NoAuto: true,
		Summary: "Delete a rule.", Returns: "`{\"ok\":true}`; `404` when unknown."},
	{Method: "POST", Path: "/api/alerts/rules/{id}/enabled", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRuleEnabled, Admin: true, NoAuto: true,
		Summary: "Switch a rule on or off.", Body: "`{\"enabled\":true|false}`", Returns: "the stored Rule"},
	{Method: "POST", Path: "/api/alerts/rules/reset-defaults", Group: grpAlerts, Access: AccessAdmin, API: apiAlertResetDefaults, Admin: true, NoAuto: true,
		Summary: "Restore the built-in rules to their shipped state (user rules are kept).", Returns: "`{\"ok\":true}`"},
	{Method: "POST", Path: "/api/alerts/test", Group: grpAlerts, Access: AccessAdmin, API: apiAlertTest, Admin: true, NoAuto: true,
		Summary: "Test a rule against the current live picture without firing anything.",
		Body:    "`{\"rule\": Rule, \"event\": {\"kind\":\"record\",\"key\":\"max_dist_km\",\"text\":\"...\"}?}` (the event only for system rules)",
		Returns: "`{\"aircraft\": n tested, \"matches\": [{icao, callsign, reg, type, text}]}` (at most 500); `400` when the rule is invalid."},
	{Method: "GET", Path: "/api/alerts/recent", Group: grpAlerts, Access: AccessAdmin, API: apiAlertRecent, Sample: "/api/alerts/recent?limit=5",
		Summary: "Recently fired alerts, newest first (in-memory ring of 500; logged ones are also in `/api/stats/events?kind=alert`).",
		Params:  []Param{{"limit", "1..500 (default 100)"}, {"after", "only alerts with an id above this"}},
		Notes:   "The same objects arrive live as SSE `event: alert`."},
	{Method: "GET", Path: "/api/alerts/highlights", Group: grpAlerts, Access: AccessAdmin, API: apiAlertHighlights,
		Summary: "Aircraft currently highlighted by a rule (also in the live picture as `aircraft[].highlight`).",
		Notes:   "`until` = Unix ms the highlight lasts without a new match (15 s hold)."},
	{Method: "GET", Path: "/api/alerts/stats", Group: grpAlerts, Access: AccessAdmin, API: apiAlertStats,
		Summary: "Alert engine counters: rules, evaluations, last evaluation time, fired / suppressed, webhook sent / failed / dropped, range baseline."},
	{Method: "GET", Path: "/api/alerts/placeholders", Group: grpAlerts, Access: AccessPublic, API: apiAlertPlaceholders,
		Summary: "Help text listing the message template placeholders (`{ident}`, `{alt}`, `{dist}` ...)."},
	{Method: "POST", Path: "/api/alerts/webhook-test", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWebhookTest, Admin: true, NoAuto: true,
		Summary: "Send a test POST to a webhook URL.", Body: "`{\"url\":\"https://...\"}`",
		Returns: "`{\"ok\":true}`; `400` invalid URL, `409` webhooks switched off (`config.alerts.webhooks`), `502` with the error when the POST failed.",
		Notes:   "Webhook payload: `{\"app\":\"AirView\",\"version\":\"...\",\"type\":\"alert\"|\"test\",\"alert\":Alert}`, `Content-Type: application/json`, 5 s timeout, no retries, no redirects, at most 30 per minute."},
	{Method: "GET", Path: "/api/alerts/export", Group: grpAlerts, Access: AccessAdmin, Raw: rawAlertExport,
		Summary: "All rules as a JSON array (download).", Returns: "JSON array of Rule, `Content-Disposition: attachment`."},
	{Method: "POST", Path: "/api/alerts/import", Group: grpAlerts, Access: AccessAdmin, API: apiAlertImport, Admin: true, NoAuto: true,
		Summary: "Import rules (all-or-nothing validation; rules with an existing id are replaced).", Body: "JSON array of Rule (at most 4 MB)",
		Returns: "`{\"imported\":n}`"},
	{Method: "GET", Path: "/api/alerts/watchlists", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWatchlists,
		Summary: "Watch-lists with their number of entries (`[{name, entries}]`)."},
	{Method: "GET", Path: "/api/alerts/watchlists/{name}", Group: grpAlerts, Access: AccessAdmin, Raw: rawAlertWatchlist, Sample: "/api/alerts/watchlists/{watchlist}",
		Summary: "The entries of one watch-list, or a download.",
		Params:  []Param{{"format", "`json` (default: `[{icao, note, added}]`) | `txt` | `csv` (download)"}},
		Returns: "JSON array of `{icao, note, added}` or a text / CSV file; `404` unknown list."},
	{Method: "POST", Path: "/api/alerts/watchlists/{name}/import", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWatchlistImport, Admin: true, NoAuto: true, LongBody: true,
		Summary: "Import ICAO addresses into a watch-list (created if needed).",
		Params:  []Param{{"replace", "`1` replaces the list instead of adding"}},
		Body:    "plain text or CSV (at most 16 MB): one address per line, optional note after a comma, semicolon or space; `#` comments",
		Returns: "`{\"imported\":n,\"rejected\":k}`"},
	{Method: "PUT", Path: "/api/alerts/watchlists/{name}/{icao}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWatchAdd, Admin: true, NoAuto: true,
		Summary: "Add (or update the note of) one address.", Body: "`{\"note\":\"...\"}` (optional)", Returns: "`{\"ok\":true}`"},
	{Method: "DELETE", Path: "/api/alerts/watchlists/{name}/{icao}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWatchRemove, Admin: true, NoAuto: true,
		Summary: "Remove one address.", Returns: "`{\"ok\":true}`; `404` when not on the list."},
	{Method: "DELETE", Path: "/api/alerts/watchlists/{name}", Group: grpAlerts, Access: AccessAdmin, API: apiAlertWatchlistDelete, Admin: true, NoAuto: true,
		Summary: "Delete a watch-list.", Returns: "`{\"ok\":true}`; `404` when unknown."},

	// ---------------------------------------------------- replay / exports
	{Method: "GET", Path: "/api/replay", Group: grpReplay, Access: AccessAdmin, API: apiReplay, Cache: ttlShort, Sample: "/api/replay?hours=0.5&step=60",
		Summary: "History replay: time-sliced pictures of all stored positions in a window, in compact arrays (tar1090 / VRS style).",
		Params: []Param{{"from, to", "window in Unix ms (default: the last hour; at most 24 h)"}, {"hours", "alternative: the last N hours"}, {"days", "alternative: the last N days"},
			{"step", "seconds between frames, 1..3600 (default: span/600, at least 5); at most 2000 frames"}},
		Notes: "`aircraft[]` lists each flight once (`icao`, `flightId`, `callsign`, `reg`, `type`, `operator`, `category` = ADS-B emitter category such as `A3` (omitted when unknown), `military`); every frame `p` row is `[aircraftIndex, lat, lon, altFt|null, gsKt|null, trackDeg|null, src, ageS]` - the newest stored point at or before the frame time if at most `staleSec` old (`ageS` = its age). Stored trails have one point per `config.storage.trailIntervalSec` and are kept `config.storage.trailRetentionDays`; in aggregator mode they keep full resolution for `aggregator.storage.trailFullDays` (2) days after the flight ended, then one point per `aggregator.storage.trailThinSec` (30 s), and `staleSec` is widened to at least trailThinSec + trailIntervalSec + 5 for windows starting before then. At most 400 000 points are read (`truncated`). Predicted positions are never stored, so they never appear here."},
	{Method: "GET", Path: "/api/history/flights/{id}/trace", Group: grpReplay, Access: AccessAdmin, API: apiFlightTrace, Sample: "/api/history/flights/{flight}/trace",
		Summary: "Full stored trail of one flight with track angles, and the guessed departure / arrival airports.",
		Notes:   "`points`: `[tMs, lat, lon, altFt|null, gsKt|null, trackDeg|null, rssi|null, src]`. `airports.departure` / `arrival` (`navdata.AirportGuess`: `airport`, `runway`, `distKm`, `heightAglFt`, `confidence` 0..1, `reason`) are null when the flight was not seen low near an airport or no airport data is imported. `404` unknown flight."},
	{Method: "GET", Path: "/api/export/flight/{file}", Group: grpReplay, Access: AccessAdmin, Raw: rawExportFlight, ContentType: ctGeoJSON, Sample: "/api/export/flight/{flight}.geojson",
		Summary: "Download one flight: `{id}.kml` (Google Earth, absolute altitudes), `{id}.geojson` (LineString [lon, lat, altM] with `properties.times`) or `{id}.csv`.",
		Returns: "`application/vnd.google-earth.kml+xml`, `application/geo+json` or `text/csv` with `Content-Disposition: attachment`; `404` unknown flight or format."},
	{Method: "GET", Path: "/api/export/live.kml", Group: grpReplay, Access: AccessAdmin, Raw: rawExportLive, ContentType: ctKML, Sample: "/api/export/live.kml?minutes=5",
		Summary: "The current picture with trails as KML.",
		Params:  []Param{{"minutes", "trail length 0..240 (default `config.ui.trailMinutes`; 0 = no trails)"}},
		Returns: "KML document: one folder per aircraft with a point (absolute altitude) and its trail. Coasting aircraft are exported at their last real position."},
	{Method: "GET", Path: "/api/export/live.geojson", Group: grpReplay, Access: AccessAdmin, Raw: rawExportLive, ContentType: ctGeoJSON, Sample: "/api/export/live.geojson?minutes=5",
		Summary: "The current picture with trails as GeoJSON.",
		Params:  []Param{{"minutes", "trail length 0..240 (default `config.ui.trailMinutes`; 0 = no trails)"}},
		Returns: "FeatureCollection: `kind=aircraft` points (icao, callsign, reg, type, operator, altFt, gsKt, track, source, predicted, lastSeen) and `kind=trail` LineStrings ([lon, lat, altM], `times`)."},
	{Method: "GET", Path: "/api/export/aircraft.csv", Group: grpReplay, Access: AccessAdmin, Raw: rawExportAircraft, ContentType: ctCSV,
		Summary: "Every airframe ever seen as CSV (streamed).",
		Returns: "`text/csv`: icao, reg, type, type_desc, operator, country, category, military, first_seen, last_seen (RFC 3339 UTC), msgs, flights, positions, max_dist_km, max_alt_ft, year."},
	{Method: "GET", Path: "/api/reports", Group: grpReplay, Access: AccessAdmin, API: apiReports, Sample: "/api/reports?hours=6&limit=3",
		Summary: "Report query (VirtualRadar style): flights in a time range filtered by callsign, registration, address, type, operator, country, military, distance, altitude, departure / arrival airport; paged and sorted.",
		Params:  params(pReport, Param{"limit", "1..1000 (default 100)"}, Param{"offset", "rows to skip"}),
		Notes:   "`total` counts all matching flights. Distances km, altitudes ft, speeds kt, signal dBFS, times Unix ms; unknown values null. Reference data comes from the aircraft table and the imported aircraft database. `dep` / `arr` are the departure / arrival airport codes (ICAO, else GPS code / ident) the engine stores once a flight is closed (about 35 min after its last message), guessed from the first / last low positions near an airport of the imported airport data; they are absent while the flight is open, not resolved yet (older flights are back-filled slowly in the background) or when no airport fits."},
	{Method: "GET", Path: "/api/reports.csv", Group: grpReplay, Access: AccessAdmin, Raw: rawReportsCSV, ContentType: ctCSV, Sample: "/api/reports.csv?hours=6&limit=5",
		Summary: "The same report as a CSV download (streamed).",
		Params:  params(pReport, Param{"limit", "1..1000000 (default 100000)"}),
		Returns: "`text/csv` with the columns of `/api/reports` rows (times RFC 3339 UTC), ending with `dep`, `arr`."},
}
